import 'dart:convert';

import 'dart:typed_data';

import 'package:flutter/material.dart';



final Uint8List groupLogoBytes = base64Decode('');

/// Presentaciones que conservan siempre el logotipo original.
enum GroupLogoVariant { clean, framed, featured }

/// Emblema institucional reutilizable.
///
/// La imagen es idéntica en los tres estilos: solo cambian el soporte,
/// la profundidad y los adornos que la rodean.
class GroupLogo extends StatelessWidget {
  const GroupLogo({
    super.key,
    this.size = 56,
    this.variant = GroupLogoVariant.framed,
    this.showBorder = true,
  }) : assert(size > 0);

  final double size;
  final GroupLogoVariant variant;
  final bool showBorder;

  static const _navy = Color(0xFF071D49);
  static const _gold = Color(0xFFD9B96D);

  @override
  Widget build(BuildContext context) {
    final dark = Theme.of(context).brightness == Brightness.dark;
    final reducedMotion = MediaQuery.of(context).disableAnimations;
    final compact = size < 60;
    final featured = variant == GroupLogoVariant.featured;
    final clean = variant == GroupLogoVariant.clean;
    final padding = clean ? 0.0 : (compact ? size * .075 : size * .085);
    final borderWidth = size >= 96 ? 1.65 : 1.15;

    final ring = dark ? const Color(0xFFE1C98C) : _gold;
    final backing = dark
        ? const [Color(0xFF172A48), Color(0xFF0B1932)]
        : const [Color(0xFFFFFFFF), Color(0xFFF0F4FB)];

    final portrait = ClipOval(
      child: Image.memory(
        groupLogoBytes,
        fit: BoxFit.contain,
        width: double.infinity,
        height: double.infinity,
        gaplessPlayback: true,
        filterQuality: FilterQuality.high,
        excludeFromSemantics: true,
      ),
    );

    if (clean) {
      return Semantics(
        label: 'Logotipo original del Grupo Amigos Verdaderos de Narcóticos Anónimos',
        image: true,
        child: SizedBox.square(dimension: size, child: portrait),
      );
    }

    return Semantics(
      label: 'Logotipo original del Grupo Amigos Verdaderos de Narcóticos Anónimos',
      image: true,
      child: SizedBox.square(
        dimension: size,
        child: AnimatedContainer(
          duration: reducedMotion ? Duration.zero : const Duration(milliseconds: 250),
          curve: Curves.easeInOut,
          padding: EdgeInsets.all(padding),
          decoration: BoxDecoration(
            shape: BoxShape.circle,
            gradient: LinearGradient(
              begin: Alignment.topLeft,
              end: Alignment.bottomRight,
              colors: featured
                  ? (dark
                      ? const [Color(0xFF314A72), _navy]
                      : const [Color(0xFFFFFFFF), Color(0xFFE4EBF8)])
                  : backing,
            ),
            border: showBorder
                ? Border.all(color: ring.withOpacity(dark ? .9 : .72), width: borderWidth)
                : null,
            boxShadow: [
              BoxShadow(
                color: dark
                    ? Colors.black.withOpacity(featured ? .32 : .20)
                    : _navy.withOpacity(featured ? .17 : .10),
                blurRadius: featured ? size * .22 : size * .13,
                offset: Offset(0, size * (featured ? .065 : .035)),
              ),
            ],
          ),
          child: DecoratedBox(
            decoration: BoxDecoration(
              shape: BoxShape.circle,
              border: Border.all(
                color: dark ? Colors.white.withOpacity(.15) : _navy.withOpacity(.1),
                width: .8,
              ),
            ),
            child: Padding(
              padding: EdgeInsets.all(compact ? 1 : 2),
              child: portrait,
            ),
          ),
        ),
      ),
    );
  }
}